{
  "name": "dsh-quota-overview",
  "version": "1.0.1",
  "description": "A DSH (DeepSeek Harness) Web plugin: a full-width sidebar quota entry shows the DeepSeek account balance and OpenCode Go usage together; clicking opens a dialog with details, live reset countdowns and inline API key setup.",
  "type": "module",
  "exports": {
    ".": "./index.js",
    "./client": "./client.js",
    "./locale/*.json": "./locale/*.json",
    "./icon": "./icon.svg"
  },
  "files": [
    "index.js",
    "client.js",
    "cordis.patch.yml",
    "locale/*.json",
    "icon.svg",
    "README.md",
    "LICENSE",
    "docs/*.png"
  ],
  "keywords": [
    "dsh",
    "dsh-plugin",
    "deepseek-harness",
    "deepseek",
    "opencode",
    "opencode-go",
    "quota",
    "balance",
    "usage",
    "sidebar",
    "plugin"
  ],
  "license": "MIT",
  "author": "joyboy-yy (https://github.com/joyboy-yy)",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/joyboy-yy/dsh-quota-overview.git"
  },
  "homepage": "https://github.com/joyboy-yy/dsh-quota-overview#readme",
  "bugs": {
    "url": "https://github.com/joyboy-yy/dsh-quota-overview/issues"
  },
  "engines": {
    "node": ">=22.19.0"
  },
  "publishConfig": {
    "registry": "https://registry.npmjs.org",
    "access": "public"
  },
  "dsh": {
    "bundle": {
      "patch": "./cordis.patch.yml"
    },
    "client": {
      "platform": "web",
      "immediately": true,
      "inject": [
        "@deepseek-ai/dsh-client-runtime",
        "@deepseek-ai/dsh-client-ui-slots"
      ]
    }
  }
}
